INSERT INTO lesson_parts (lesson_id, part_order, title, kind, status, file_path, test_code, pass_percent) SELECT l.id, 2, 'Course Overview Quiz', 'quiz', 'ready', 'resources/quizzes/class_quiz.php?test_code=OVW_PTE_3MO', 'OVW_PTE_3MO', 70 FROM lessons l JOIN modules m ON m.id = l.module_id AND m.module_order = 1 JOIN courses c ON c.id = l.course_id AND c.folder_name = 'PTE_Gen_3Mo' WHERE l.lesson_order = 1 AND NOT EXISTS (SELECT 1 FROM lesson_parts z WHERE z.lesson_id = l.id AND z.part_order = 2);
