UPDATE lesson_parts p JOIN lessons l ON l.id = p.lesson_id JOIN modules m ON m.id = l.module_id AND m.module_order = 1 JOIN courses c ON c.id = l.course_id AND c.folder_name = 'CELPIP_Gen_2Mo' SET p.part_order = 3 WHERE l.lesson_order = 1 AND p.kind = 'placement_test' AND p.part_order = 2;
UPDATE lessons l JOIN modules m ON m.id = l.module_id AND m.module_order = 1 JOIN courses c ON c.id = l.course_id AND c.folder_name = 'CELPIP_Gen_2Mo' SET l.title = REPLACE(l.title, 'Course Introduction + Foundational English Assessment', 'Course Introduction + Course Overview Quiz + Foundational English Assessment') WHERE l.lesson_order = 1;

