-- Check: every course's Class 1 = Course Introduction, Course Overview Quiz, Foundational English Assessment.
SELECT c.folder_name, p.part_order, p.title, p.status, p.test_code FROM lesson_parts p JOIN lessons l ON l.id = p.lesson_id JOIN modules m ON m.id = l.module_id AND m.module_order = 1 JOIN courses c ON c.id = l.course_id WHERE l.lesson_order = 1 AND c.folder_name IN ('CELPIP_Gen_2Mo', 'CELPIP_Gen_3Mo', 'IELTS_Gen_2Mo', 'IELTS_Gen_Mst', 'IELTS_Aca_2Mo', 'IELTS_Aca_3Mo', 'PTE_Gen_2Mo', 'PTE_Gen_3Mo') ORDER BY c.folder_name, p.part_order;
SELECT t.code, COUNT(DISTINCT x.id) AS questions, SUM(o.is_correct) AS right_answers FROM tests t JOIN questions x ON x.test_id = t.id JOIN question_options o ON o.question_id = x.id WHERE t.code IN ('OVW_CELPIP_2MO', 'OVW_CELPIP_3MO', 'OVW_IELTS_GT_2MO', 'OVW_IELTS_GT_3MO', 'OVW_IELTS_ACA_2MO', 'OVW_IELTS_ACA_3MO', 'OVW_PTE_2MO', 'OVW_PTE_3MO') GROUP BY t.code;

